-- Phong Than 2026-10-03 (agent vantieu/vanluong): Van Luong (grain escort), rebuilt in Lua.
-- ASCII file generated by scratchpad\vantieu\gen.py. Documented in docs\features\van-luong-van-tieu-phong-than-20261003.md.
-- One script for every Van Luong NPC, so they share one Lua state:
--   * Tieu Su Dong Quan (map 1014, VNG placement "\script\yun_biao\tong_guan_biao_shi.lua", rebound here by
--     script\phongthan\ext\vanluong.lua): accept a run (main road / short cut with ambushes), cancel, reset cart;
--   * Luong Thao Quan (map 1014, spawned by the ext tick, param 0 = 21401): delivery and reward;
--   * the grain cart and the bandits: OnTimer / LastDamage / DeathSelf / Revive;
--   * also the timer script of the Van Tieu 2004 cart (\script\yun_biao\*, patched in ptfix).
-- VNG data reused: taskinfo 64 "Van luong" (deliver grain for Tong binh Truong Que Phuong, 6 runs, reward
-- level x exp / level x money), NPC rows 556 (grain cart) and 979 (bandit), placement of the 1014 Tieu Su.
Include("\\script\\phongthan\\vanluong\\vl_lib.lua")
-- 2026-10-03 (coordinator, daily3 hook): whoever destroys SOMEONE ELSE's cart becomes a Luc Lam bandit
-- (grain cart: Dao Tac, escort cart: Kim Bai). PTD3_LL_GrantFlag(kind) runs with PlayerIndex = the robber.
Include("\\script\\phongthan\\daily3\\d3_lib.lua")
function PTVL_D3Err(m) end

PTVL_HEAD_GIVER = "<color=green>Ti\170u S\173 \167\229ng Quan<color>: "
PTVL_HEAD_DEST = "<color=green>L\173\172ng Th\182o Quan<color>: "

-- 2026-10-03 (coordinator): the engine calls main(npcIndex) (KPlayer::DialogNpc) and never sets a
-- DialogNpcIdx global; the old code therefore never reached the cart / Luong Thao Quan branches in game.
function main(npcidx)
	local n = npcidx
	if not n or n <= 0 then n = DialogNpcIdx end
	local mg = 0
	if n and n > 0 then mg = GetNpcParam(n, 0) end
	if mg == PTVL_MG_CART or mg == PTVL_MG_TIEU or mg == PTVL_MG_DEAD then
		PTVL_CartTalk(n)
	elseif mg == PTVL_MG_DEST then
		PTVL_DestTalk(n)
	elseif mg == PTVL_MG_BANDIT then
		return
	else
		PTVL_GiverTalk()
	end
end

function no()
	CloseDialog()
end

