function vl_info()
	Say(PTVL_HEAD_GIVER .. "M\231i ng\181y nh\203n t\232i \174a <color=yellow>" .. PTVL_DAILY .. "<color> chuy\213n, c\202p " .. PTVL_MINLV .. " tr\235 l\170n. Xe l\173\172ng \174i theo ng\173\234i \184p v\203n; gi\247 xe trong t\199m m\190t, r\234i xe qu\184 2 ph\243t l\181 m\202t xe. Th\234i h\185n <color=yellow>15 ph\243t<color>. \167\173\234ng t\190t s\207 g\198p <color=red>2 \174\238t th\230 ph\216<color>: c\182 \174\233i v\181 \174\229ng h\181nh \174\210u c\227 th\211 \174\184nh, m\231i t\170n b\222 h\185 \174\173\238c th\173\235ng th\170m. \167\213n n\172i h\183y b\184o v\237i L\173\172ng Th\182o Quan \174\211 nh\203n th\173\235ng.", 2,
		"Tr\235 l\185i/main", "K\213t th\243c \174\232i tho\185i/no")
