function vl_take_safe()
	PTVL_Take(1)
end

function vl_take_ambush()
	PTVL_Take(2)
end

function PTVL_Take(mode)
	if GetLevel() < PTVL_MINLV then
		Talk(1, "no", PTVL_HEAD_GIVER .. "\167\173\234ng \174i nguy hi\211m, c\202p " .. PTVL_MINLV .. " tr\235 l\170n ta m\237i giao xe l\173\172ng.")
		return
	end
	if PTVL_VLState() == 1 or PTVL_VTState() == 1 then
		Talk(1, "no", PTVL_HEAD_GIVER .. "Ng\173\172i \174ang \184p v\203n m\233t xe r\229i.")
		return
	end
	if PTVL_Runs() >= PTVL_DAILY then
		Talk(1, "no", PTVL_HEAD_GIVER .. "H\171m nay ng\173\172i \174\183 \184p v\203n \174\241 " .. PTVL_DAILY .. " chuy\213n, ng\181y mai h\183y quay l\185i.")
		return
	end
	if GetWorldPos() ~= PTVL_MAP then return end
	local npc, ci = PTVL_SpawnCart(mode)
	if not npc or npc <= 0 then
		Talk(1, "no", PTVL_HEAD_GIVER .. "Xe l\173\172ng ch\173a chu\200n b\222 xong, l\184t n\247a quay l\185i.")
		return
	end
	SetTask(PTVL_T_STATE, 1)
	SetTask(PTVL_T_CART, npc)
	SetTask(PTVL_T_CARTID, PTVL_N(GetNpcID(npc)))
	SetTask(PTVL_T_DEADLINE, PTVL_Now() + PTVL_TIME)
	SetTask(PTVL_T_MODE, mode)
	SetTask(PTVL_T_KILLS, 0)
	SetTask(PTVL_T_RUNS, PTVL_Runs() + 1)
	CloseDialog()
	local road = "\174\173\234ng l\237n"
	if mode == 2 then road = "\174\173\234ng t\190t, coi ch\245ng th\230 ph\216" end
	Msg2Player("Nh\203n <color=yellow>xe l\173\172ng<color> (" .. road .. "). H\233 t\232ng \174\213n <color=yellow>L\173\172ng Th\182o Quan<color> (" .. PTVL_DEST[2] .. "/" .. PTVL_DEST[3] .. ") trong 15 ph\243t.")
	TopMessage("Xe l\173\172ng \174\183 s\189n s\181ng, h\183y h\233 t\232ng \174\213n L\173\172ng Th\182o Quan!")
end

function vl_cancel()
	if PTVL_VLState() ~= 1 then return end
	local cart = GetTask(PTVL_T_CART)
	SetNpcParam(cart, 0, PTVL_MG_DEAD)
	PTVL_ClearVL()
	SetTask(PTVL_T_LAST, 4)
	PTVL_CartRemove(cart)
	Msg2Player(PTVL_LASTMSG[4])
	CloseDialog()
end

-- anti-stuck: bring the cart next to the player (same map, cart alive)
function vl_callcart()
	if PTVL_VLState() ~= 1 then return end
	local cart = GetTask(PTVL_T_CART)
	local w, x, y = GetNpcPos(cart)
	local pw, px, py = GetWorldPos()
	if w ~= pw then
		Talk(1, "no", PTVL_HEAD_GIVER .. "Xe l\173\172ng kh\171ng \235 b\182n \174\229 n\181y.")
		return
	end
	SetNpcPos(cart, px + 1, py + 1)
	SetNpcParam(cart, 15, 0)
	Msg2Player("\167\183 k\208o xe l\173\172ng v\210 b\170n c\185nh.")
	CloseDialog()
end

-- ---------------------------------------------------------------- Luong Thao Quan (destination)
function PTVL_DestTalk(dest)
	if PTVL_VLState() ~= 1 then
		Say(PTVL_HEAD_DEST .. "Qu\169n l\173\172ng c\241a T\230ng binh Tr\173\172ng Qu\213 Ph\173\172ng l\243c n\181o c\242ng thi\213u. Mu\232n gi\243p th\215 \174\213n g\198p <color=yellow>Ti\170u S\173<color> \235 \167\229ng Quan (" .. 1454 .. "/" .. 3150 .. ").", 1, "K\213t th\243c \174\232i tho\185i/no")
		return
	end
	local cart = GetTask(PTVL_T_CART)
	local w, x, y = GetNpcPos(cart)
	local dw, dx, dy = GetNpcPos(dest)
	if w ~= dw or PTVL_Dist2(x, y, dx, dy) > 225 then
		Talk(1, "no", PTVL_HEAD_DEST .. "Xe l\173\172ng \174\169u? H\183y \174\173a xe \174\213n s\184t \174\169y r\229i h\183y b\184o.")
		return
	end
	local lv = GetLevel()
	local mode = GetTask(PTVL_T_MODE)
	local kills = GetTask(PTVL_T_KILLS)
	local exp = lv * 2000
	local money = lv * 300
	if mode == 2 then
		exp = floor(exp * 3 / 2) + kills * lv * 150
		money = lv * 500
	end
	SetNpcParam(cart, 0, PTVL_MG_DEAD)
	PTVL_ClearVL()
	SetTask(PTVL_T_LAST, 1)
	SetTask(PTVL_T_KILLS, 0)
	PTVL_CartRemove(cart)
	AddOwnExp(exp)
	Earn(money)
	Msg2Player("Giao xe l\173\172ng th\181nh c\171ng: <color=yellow>" .. exp .. "<color> kinh nghi\214m, <color=yellow>" .. money .. "<color> l\173\238ng (th\230 ph\216 b\222 h\185: " .. kills .. ").")
	Talk(1, "no", PTVL_HEAD_DEST .. "T\232t l\190m! Qu\169n l\173\172ng \174\183 \174\241, T\230ng binh s\207 ghi nh\237 c\171ng lao c\241a ng\173\172i. \167\169y l\181 ph\199n th\173\235ng.")
end

-- ---------------------------------------------------------------- cart click
function PTVL_CartTalk(cart)
	if GetNpcParam(cart, 0) == PTVL_MG_DEAD then return end
	if GetNpcParam(cart, 9) == 2 then return end
	if PTVL_VLState() == 1 and GetTask(PTVL_T_CART) == cart then
		local left = GetTask(PTVL_T_DEADLINE) - PTVL_Now()
		Talk(1, "no", "Xe l\173\172ng c\241a ng\173\172i. C\223n <color=yellow>" .. PTVL_Min(left) .. "<color> ph\243t \174\211 \174\213n L\173\172ng Th\182o Quan (" .. PTVL_DEST[2] .. "/" .. PTVL_DEST[3] .. ").")
	else
		Talk(1, "no", "Xe l\173\172ng c\241a ng\173\234i kh\184c \174ang \184p v\203n.")
	end
end

-- ---------------------------------------------------------------- engine callbacks
function OnTimer(npc)
	local mg = GetNpcParam(npc, 0)
	if mg == PTVL_MG_CART or mg == PTVL_MG_TIEU or mg == PTVL_MG_DEAD then
		PTVL_CartTick(npc)
	elseif mg == PTVL_MG_BANDIT then
		PTVL_BanditTick(npc)
	end
end

function LastDamage(npc)
	local mg = GetNpcParam(npc, 0)
	if mg == PTVL_MG_BANDIT then
		PTVL_BanditKilled(npc)
	elseif mg == PTVL_MG_CART or mg == PTVL_MG_TIEU then
		if PTD3_LL_GrantFlag and PlayerIndex and PlayerIndex > 0 and PlayerIndex ~= GetNpcParam(npc, 1) then
			local kind = 1
			if mg == PTVL_MG_TIEU then kind = 2 end
			local robber = PlayerIndex
			call(PTD3_LL_GrantFlag, { kind }, "x", PTVL_D3Err)
			PlayerIndex = robber
		end
		PTVL_OnCartDown(npc)
	end
end

function DeathSelf(npc)
	local mg = GetNpcParam(npc, 0)
	if mg == PTVL_MG_CART or mg == PTVL_MG_TIEU then
		PTVL_OnCartDown(npc)
	elseif mg == PTVL_MG_BANDIT then
		SetNpcParam(npc, 3, 1)
	end
end

function Revive(npc)
	PTVL_OnRevive(npc)
end
